/* Pixel sprite manifest + renderer for nyanwan-rx.
 *
 * Sheets live at assets/sprites/<cat>/<variant>/<anim>.png — horizontal
 * strips of square frames. SPRITES is generated by scanning the sheets
 * (anims: name -> frame count; cx/foot/ch describe where the artwork sits
 * inside the padded frame, measured from the first idle frame's alpha).
 *
 * spriteImg() renders one as an animated element compatible with the
 * .sprite emoji placeholders in game.js — same (x%, y%) anchor, feet
 * planted where an emoji's feet would land — so the two mix freely.
 * Returns null for unknown variants; callers fall back to emoji.
 */

export interface SpriteDef {
  cat: "pets" | "humans";
  frame: number;
  scale: number;
  cx: number;
  cw: number;
  foot: number;
  ch: number;
  anims: Record<string, number>;
}

export interface SpriteOpts {
  enter?: boolean;
  status?: string;
  flip?: boolean;
  scale?: number;
  pose?: string;
}

