export const HUMAN_SPRITES = Object.keys(SPRITES).filter(id => SPRITES[id].cat === "humans");

const FRAME_MS = 120; // per animation frame

/* Animated strip element. (x%, y%) matches the emoji sprites' anchor —
 * roughly the top-left of a ~40px emoji — so the artwork's feet are placed
 * at anchor + (20px, 44px), same as an emoji's feet. */
export function spriteImg(id: string, anim: string, x: number, y: number, opts: SpriteOpts = {}): string | null {
  const s = SPRITES[id];
  if (!s) return null;
  const a = s.anims[anim] ? anim : (s.anims.idle ? "idle" : Object.keys(s.anims)[0]);
  const frames = s.anims[a];
  const k = opts.scale || s.scale;
  const px = s.frame * k;
  const style = [
    `width:${px}px`, `height:${px}px`,
    `background-image:url(${import.meta.env.BASE_URL}assets/sprites/${s.cat}/${id}/${a}.png)`,
    `background-size:${frames * px}px ${px}px`,
    `--shift:${-frames * px}px`,
    `animation-duration:${frames * FRAME_MS}ms`,
    `animation-timing-function:steps(${frames})`,
    `margin-left:${Math.round(20 - s.cx * k)}px`,
    `margin-top:${Math.round(44 - s.foot * k)}px`,
    opts.flip ? "scale:-1 1" : "",
  ].join(";");
  const status = opts.status
    ? `<span class="s-status" style="top:${Math.round(44 - (s.ch * k) - 30)}px;left:${20 + Math.round(s.ch * k * 0.4)}px;right:auto">${opts.status}</span>`
    : "";
  return `<div class="sprite${opts.enter ? " enter" : ""}" style="left:${x}%;top:${y}%">
    ${status}<div class="s-px" style="${style}"></div></div>`;
}

/* Same animated strip, but as a flow-friendly inline-block cropped to the
 * artwork's content box, sized so the content is ~target px tall. Drops in
 * wherever an emoji of that font-size would go (minigame stages, HUD, …). */
export function spriteInline(id: string, target: number, anim = "idle"): string | null {
  const s = SPRITES[id];
  if (!s) return null;
  const a = s.anims[anim] ? anim : (s.anims.idle ? "idle" : Object.keys(s.anims)[0]);
  const frames = s.anims[a];
  const k = Math.max(1, Math.round(target / s.ch));
  const px = s.frame * k;
  const inner = [
    `width:${px}px`, `height:${px}px`,
    `background-image:url(${import.meta.env.BASE_URL}assets/sprites/${s.cat}/${id}/${a}.png)`,
    `background-size:${frames * px}px ${px}px`,
    `--shift:${-frames * px}px`,
    `animation-duration:${frames * FRAME_MS}ms`,
    `animation-timing-function:steps(${frames})`,
    `position:absolute`,
    `left:${Math.round(s.cw / 2 - s.cx) * k}px`,
    `top:${(s.ch - s.foot) * k}px`,
  ].join(";");
  return `<span class="s-in" style="width:${s.cw * k}px;height:${s.ch * k}px">
    <span class="s-px" style="${inner}"></span></span>`;
}
